    @%p0 bra RET;
    add.s32 %r12, %r8, %r11;
    add.s32 %r13, %r12, %r11;
    setp.lt.s32 %p1, %r12, %r1;
    setp.lt.s32 %p2, %r13, %r1;
    cvt.u64.u32 %rd3, %r4;
    cvt.u64.u32 %rd4, %r2;
    cvt.u64.u32 %rd5, %r1;
    cvt.u64.u32 %rd6, %r8;
    cvt.u64.u32 %rd7, %r11;
    mul.lo.u64 %rd8, %rd3, %rd4;
    mul.lo.u64 %rd8, %rd8, %rd5;
    add.u64 %rd8, %rd8, %rd6;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd9, %rd1, %rd8;
    shl.b64 %rd10, %rd7, 2;
    add.u64 %rd11, %rd9, %rd10;
