    @!%p3 bra DONE;
    add.u64 %rd9, %rd9, %rd13;
    add.u64 %rd11, %rd11, %rd13;
    add.u64 %rd12, %rd12, %rd13;
    ld.global.cg.f32 %f4, [%rd9];
    max.f32 %f1, %f1, %f4;
    @%p1 ld.global.cg.f32 %f5, [%rd11];
    @%p1 max.f32 %f2, %f2, %f5;
    @%p2 ld.global.cg.f32 %f6, [%rd12];
